-- Filmovi i serije + Priroda i društvo: migracija + samo nova pitanja (462). Sigurno za ponovno pokretanje.

-- New question categories: films & TV series, nature & society.
alter table public.questions drop constraint if exists questions_category_check;
alter table public.questions add constraint questions_category_check
  check (category in ('hrvatska','opce','nogomet','sport','geografija','matematika','stihovi','igrice','filmovi','priroda'));

on conflict (question) do update set category = excluded.category, answer = excluded.answer,
  aliases = excluded.aliases, wrong = excluded.wrong, usage = excluded.usage;

select category, usage, count(*) from public.questions where category in ('filmovi','priroda') group by 1, 2 order by 1, 2;
